solution.solution.js:
function average(...numbers) {
  if (numbers.length === 0) return 0;
  let sum = 0;
  for (const n of numbers) sum += n;
  return sum / numbers.length;
}

function applyTimes(f, times, start) {
  let value = start;
  for (let i = 0; i < times; i++) value = f(value);
  return value;
}

function compose(...fns) {
  return x => {
    let value = x;
    for (let i = fns.length - 1; i >= 0; i--) value = fns[i](value);
    return value;
  };
}

unitTests:
test("average of rest parameters", () => {
  checkEq(average(), 0);
  checkEq(average(4), 4);
  checkEq(average(1, 2, 3, 4), 2.5);
  checkEq(average(...[10, 20]), 15);
});

test("apply a function repeatedly", () => {
  checkEq(applyTimes(x => x * 2, 3, 1), 8);
  checkEq(applyTimes(x => x + "!", 2, "hi"), "hi!!");
  checkEq(applyTimes(x => x * 2, 0, 5), 5);
});

test("compose right to left", () => {
  const inc = x => x + 1;
  const dbl = x => x * 2;
  checkEq(compose(inc, dbl)(5), 11);
  checkEq(compose(dbl, inc)(5), 12);
  checkEq(compose(inc, inc, inc)(0), 3);
  checkEq(compose()(7), 7);
});

